fn run_instrumented_reference(args: &LayerTraceRunArgs) -> Result<Value> {
    let reference_root = normalize_path(&args.reference_root)?;
    let cpp_root = normalize_path(&args.cpp_root)?;
    let patch = normalize_path(&args.patch)?;
    let plan_path = normalize_path(&args.plan)?;
    let sidecar = normalize_path(&args.sidecar)?;
    let build_dir = reference_root.join("build");
    let selected_exe = build_dir.join("bin").join(exe_name("llama-cli"));
    let generated_lut_header = reference_root.join("include/bitnet-lut-kernels.h");
    let generated_kernel_config = reference_root.join("include/kernel_config.ini");
    let plan_result = read_json(&plan_path);
    let plan_read_success = plan_result.is_ok();
    let plan = plan_result.unwrap_or(Value::Null);
    let reference_argv = reference_argv(&plan).unwrap_or_default();

    if let Some(parent) = sidecar.parent() {
        fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
    }
    if sidecar.exists() {
        fs::remove_file(&sidecar)
            .with_context(|| format!("removing stale {}", sidecar.display()))?;
    }

    let reference_status_before = git_status(&reference_root);
    let cpp_status_before = git_status(&cpp_root);
    let clean_before = capture_success_empty(&reference_status_before)
        && capture_success_empty(&cpp_status_before);

    let mut blocked_reasons = Vec::<String>::new();
    if !reference_root.is_dir() {
        blocked_reasons.push("reference_root_missing".to_string());
    }
    if !cpp_root.is_dir() {
        blocked_reasons.push("reference_llama_cpp_root_missing".to_string());
    }
    if !patch.is_file() {
        blocked_reasons.push("reference_layer_trace_patch_missing".to_string());
    }
    if !plan_path.is_file() {
        blocked_reasons.push("reference_plan_missing".to_string());
    }
    if plan_path.is_file() && !plan_read_success {
        blocked_reasons.push("reference_plan_json_invalid".to_string());
    }
    if plan_path.is_file() && reference_argv.is_empty() {
        blocked_reasons.push("reference_plan_command_argv_missing".to_string());
    }
    if !build_dir.is_dir() {
        blocked_reasons.push("reference_build_dir_missing".to_string());
    }
    if !clean_before {
        blocked_reasons.push("reference_external_worktree_not_clean_before_run".to_string());
    }

    let generated_lut_header_exists_before = generated_lut_header.is_file();
    let generated_kernel_config_exists_before = generated_kernel_config.is_file();
    let mut generated_lut_header_exists_after_codegen = generated_lut_header_exists_before;
    let mut generated_kernel_config_exists_after_codegen = generated_kernel_config_exists_before;
    let mut compatibility = Vec::<Value>::new();
    let mut codegen_capture = None;
    let mut patch_apply = None;
    let mut build_capture = None;
    let mut run_capture = None;

    if blocked_reasons.is_empty() && !generated_lut_header_exists_before {
        codegen_capture = Some(run_reference_kernel_codegen(&reference_root)?);
        generated_lut_header_exists_after_codegen = generated_lut_header.is_file();
        generated_kernel_config_exists_after_codegen = generated_kernel_config.is_file();
        if !codegen_capture.as_ref().is_some_and(|capture| capture.success) {
            blocked_reasons.push("reference_kernel_codegen_failed".to_string());
        }
        if !generated_lut_header.is_file() {
            blocked_reasons.push("reference_generated_lut_header_missing".to_string());
        }
    }

    if blocked_reasons.is_empty() {
        compatibility = apply_windows_reference_compatibility_fixes(&reference_root)?;
        patch_apply = Some(run_git(&cpp_root, &["apply", &path_to_string(&patch)])?);
        if !patch_apply.as_ref().is_some_and(|capture| capture.success) {
            blocked_reasons.push("reference_layer_trace_patch_apply_failed".to_string());
        }
    }

    if blocked_reasons.is_empty() {
        build_capture = Some(build_reference_cli(&reference_root, &build_dir)?);
        if !build_capture.as_ref().is_some_and(|capture| capture.success) {
            blocked_reasons.push("reference_layer_trace_build_failed".to_string());
        }
    }

    if blocked_reasons.is_empty() {
        if !selected_exe.is_file() {
            blocked_reasons.push("reference_layer_trace_executable_missing".to_string());
        } else if reference_argv.is_empty() {
            blocked_reasons.push("reference_plan_command_argv_missing".to_string());
        } else {
            let mut argv = reference_argv.clone();
            argv[0] = path_to_string(&selected_exe);
            run_capture = Some(run_reference_with_sidecar(
                &argv,
                &sidecar,
                args.trace_layer,
                args.first_values_limit,
            )?);
            if !run_capture.as_ref().is_some_and(|capture| capture.success) {
                blocked_reasons.push("reference_layer_trace_run_failed".to_string());
            }
        }
    }

    let sidecar_value = if sidecar.is_file() { Some(read_json(&sidecar)?) } else { None };
    if run_capture.as_ref().is_some_and(|capture| capture.success) && sidecar_value.is_none() {
        blocked_reasons.push("reference_first_token_layer_trace_sidecar_missing".to_string());
    }

    let cleanup_capture = if reference_root.is_dir() && cpp_root.is_dir() {
        Some(cleanup_reference_sources(
            &reference_root,
            &cpp_root,
            &generated_lut_header,
            generated_lut_header_exists_before,
            &generated_kernel_config,
            generated_kernel_config_exists_before,
        )?)
    } else {
        None
    };
    let reference_status_after = git_status(&reference_root);
    let cpp_status_after = git_status(&cpp_root);
    let clean_after =
        capture_success_empty(&reference_status_after) && capture_success_empty(&cpp_status_after);
    if !clean_after {
        blocked_reasons.push("reference_external_worktree_not_clean_after_run".to_string());
    }

    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();
    let record_count = sidecar_value
        .as_ref()
        .and_then(|sidecar| sidecar.pointer("/records"))
        .and_then(Value::as_array)
        .map_or(0, Vec::len);
    let reference_layer_trace_available =
        sidecar_value.is_some() && record_count > 0 && blocked_reasons.is_empty();

    Ok(json!({
        "schema_version": 1,
        "receipt_type": "bitnet_reference_layer_trace_run",
        "diagnostic": "bitnet_reference_layer_trace_run",
        "producer": "cargo xtask bitnet-reference-layer-trace-run",
        "created_at": chrono::Utc::now().to_rfc3339(),
        "diagnostic_only": true,
        "promotion_allowed": false,
        "claim_allowed": false,
        "classification": "diagnostic_only",
        "paths": {
            "reference_root": path_to_string(&reference_root),
            "cpp_root": path_to_string(&cpp_root),
            "patch": path_to_string(&patch),
            "plan": path_to_string(&plan_path),
            "build_dir": path_to_string(&build_dir),
            "selected_executable": path_to_string(&selected_exe),
            "sidecar": path_to_string(&sidecar),
        },
        "model": plan.pointer("/model").cloned().unwrap_or(Value::Null),
        "prompt_identity": plan.pointer("/prompt_identity").cloned().unwrap_or(Value::Null),
        "preflight": {
            "reference_root_exists": reference_root.is_dir(),
            "cpp_root_exists": cpp_root.is_dir(),
            "patch_exists": patch.is_file(),
            "plan_exists": plan_path.is_file(),
            "build_dir_exists": build_dir.is_dir(),
            "external_worktrees_clean_before_run": clean_before,
            "generated_lut_header": {
                "path": path_to_string(&generated_lut_header),
                "exists_before": generated_lut_header_exists_before,
                "exists_after_codegen": generated_lut_header_exists_after_codegen,
            },
            "generated_kernel_config": {
                "path": path_to_string(&generated_kernel_config),
                "exists_before": generated_kernel_config_exists_before,
                "exists_after_codegen": generated_kernel_config_exists_after_codegen,
            },
            "reference_status_before": capture_json(reference_status_before.as_ref()),
            "cpp_status_before": capture_json(cpp_status_before.as_ref()),
            "first_values_limit_env": std::env::var("BITNET_RS_REFERENCE_LAYER_TRACE_FIRST_VALUES_LIMIT").ok(),
            "first_values_limit_arg": args.first_values_limit,
            "first_values_limit_effective": args
                .first_values_limit
                .or_else(|| std::env::var("BITNET_RS_REFERENCE_LAYER_TRACE_FIRST_VALUES_LIMIT").ok().and_then(|value| value.parse().ok())),
            "trace_layer": args.trace_layer,
        },
        "kernel_codegen": capture_json(codegen_capture.as_ref()),
        "compatibility_fixes": compatibility,
        "patch_apply": capture_json(patch_apply.as_ref()),
        "build": capture_json(build_capture.as_ref()),
        "reference_run": capture_json(run_capture.as_ref()),
        "sidecar": {
            "exists": sidecar.is_file(),
            "sha256": sidecar.is_file().then(|| sha256_bytes(&fs::read(&sidecar).unwrap_or_default())),
            "record_count": record_count,
            "receipt": sidecar_value,
            "policy": "reference-side layer trace is diagnostic evidence only until compared with Rust CPU and strict A770 layer traces",
        },
        "cleanup": {
            "source_restore": capture_json(cleanup_capture.as_ref()),
            "external_worktrees_clean_after_run": clean_after,
            "reference_status_after": capture_json(reference_status_after.as_ref()),
            "cpp_status_after": capture_json(cpp_status_after.as_ref()),
        },
        "decision": {
            "reference_layer_trace_available": reference_layer_trace_available,
            "current_blocked_reasons": blocked_reasons,
            "next_when_available": "compare reference stage trace against Rust CPU and strict A770 trace receipts before changing Rust model math",
        },
        "not_claims": CRITICAL_NOT_CLAIMS,
    }))
}

fn compare_reference_layer_trace(args: &LayerTraceCompareArgs) -> Result<Value> {
    let reference_path = normalize_path(&args.reference)?;
    let cpu_trace_dir = normalize_path(&args.cpu_trace_dir)?;
    let cpu_f64_trace_dir = match &args.cpu_f64_trace_dir {
        Some(path) => Some(normalize_path(path)?),
        None => None,
    };
    let a770_trace_dir = match &args.a770_trace_dir {
        Some(path) => Some(normalize_path(path)?),
        None => None,
    };

    let reference_json = read_json(&reference_path)?;
    let reference_records = read_reference_records(&reference_json)?;
    let model_path = reference_json
        .pointer("/model/model_path")
        .and_then(Value::as_str)
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(DEFAULT_BITNET_MODEL));
    let model_path = normalize_path(&model_path)?;
    let cpu_record_list = read_rust_trace_records(&cpu_trace_dir)?;
    let cpu_records = rust_trace_stage_map(cpu_record_list.clone());
    let (cpu_f64_record_list, cpu_f64_records) = match &cpu_f64_trace_dir {
        Some(dir) => {
            let records = read_rust_trace_records(dir)?;
            let record_map = rust_trace_stage_map(records.clone());
            (Some(records), Some(record_map))
        }
        None => (None, None),
    };
    let (a770_record_list, a770_records) = match &a770_trace_dir {
        Some(dir) => {
            let records = read_rust_trace_records(dir)?;
            let map = rust_trace_stage_map(records.clone());
            (Some(records), Some(map))
        }
        None => (None, None),
    };

    let stage_mapping = reference_stage_mapping();
    let mut cpu_comparison = compare_reference_to_rust_with_records_with_model(
        &reference_records,
        &cpu_records,
        &cpu_record_list,
        &stage_mapping,
        Some(&model_path),
    );
    if let (Some(cpu_f64_record_list), Some(cpu_f64_records)) =
        (&cpu_f64_record_list, &cpu_f64_records)
    {
        let frontier = cpu_comparison
            .pointer("/layer_0_prefix_drift_frontier")
            .cloned()
            .unwrap_or(Value::Null);
        let f64_capture = layer_attention_norm_f64_capture_for_value_projection(
            &reference_records,
            &cpu_records,
            cpu_f64_records,
            &frontier,
            0,
        );
        let f64_downstream = layer_attention_norm_f64_downstream_effect(
            &reference_records,
            cpu_f64_record_list,
            cpu_f64_records,
            &cpu_comparison,
            &f64_capture,
            0,
        );
        cpu_comparison["layer_0_attention_norm_f64_downstream_effect"] = f64_downstream;
        cpu_comparison["layer_0_attention_norm_f64_capture_for_value_projection"] = f64_capture;
    }
    let a770_comparison =
        a770_records.as_ref().zip(a770_record_list.as_ref()).map(|(records, record_list)| {
            compare_reference_to_rust_with_records_with_model(
                &reference_records,
                records,
                record_list,
                &stage_mapping,
                Some(&model_path),
            )
        });

    let mut blocked_reasons = Vec::<String>::new();
    let cpu_scope_mismatch_count =
        cpu_comparison["scope_mismatch_count"].as_u64().unwrap_or_default();
    if cpu_scope_mismatch_count > 0 {
        blocked_reasons.push("rust_cpu_reference_layer_trace_scope_unaligned".to_string());
    } else if cpu_comparison["first_material_mismatch"].is_null() {
        blocked_reasons
            .push("rust_cpu_reference_layer_trace_no_material_mismatch_found".to_string());
    } else {
        blocked_reasons.push("rust_cpu_reference_layer_trace_divergence_unresolved".to_string());
    }
    if a770_comparison
        .as_ref()
        .and_then(|comparison| comparison["scope_mismatch_count"].as_u64())
        .unwrap_or_default()
        > 0
    {
        blocked_reasons.push("strict_a770_reference_layer_trace_scope_unaligned".to_string());
    }
    if a770_trace_dir.is_none() {
        blocked_reasons.push("strict_a770_trace_dir_not_supplied".to_string());
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    Ok(json!({
        "schema_version": 1,
        "receipt_type": "bitnet_reference_layer_trace_compare",
        "diagnostic": "bitnet_reference_layer_trace_compare",
        "producer": "cargo xtask bitnet-reference-layer-trace-compare",
        "created_at": chrono::Utc::now().to_rfc3339(),
        "diagnostic_only": true,
        "promotion_allowed": false,
        "claim_allowed": false,
        "classification": "diagnostic_only",
        "inputs": {
            "reference": path_to_string(&reference_path),
            "cpu_trace_dir": path_to_string(&cpu_trace_dir),
            "cpu_f64_trace_dir": cpu_f64_trace_dir.as_ref().map(|path| path_to_string(path)),
            "a770_trace_dir": a770_trace_dir.as_ref().map(|path| path_to_string(path)),
            "model": path_to_string(&model_path),
        },
        "reference": {
            "record_count": reference_records.len(),
            "stages": reference_records
                .iter()
                .map(|record| json!({
                    "name": record.name,
                    "stage": record.stage,
                    "graph_index": record.graph_index,
                    "graph_op": record.graph_op,
                    "graph_sources": record.graph_sources,
                    "view_source": record.view_source,
                    "view_offset": record.view_offset,
                    "full_shape": record.full_shape,
                    "sample_offset": record.sample_offset,
                    "token_axis": record.token_axis,
                    "sampled_token_index": reference_sampled_token_index(record),
                    "shape": record.shape,
                    "dtype": record.dtype,
                    "nelements": record.nelements,
                    "rms": record.rms,
                    "values_available": record.values_available,
                }))
                .collect::<Vec<_>>(),
        },
        "stage_mapping": stage_mapping
            .iter()
            .map(|(reference, rust)| json!({"reference": reference, "rust": rust}))
            .collect::<Vec<_>>(),
        "cpu": cpu_comparison,
        "a770": a770_comparison,
        "decision": {
            "reference_layer_trace_compared": true,
            "claim_allowed": false,
            "current_blocked_reasons": blocked_reasons,
            "next_action": "use the first material mismatch to choose the next Rust/reference divergence capture; do not change model math until the mismatching boundary is stable",
        },
        "not_claims": CRITICAL_NOT_CLAIMS,
    }))
}

fn capture_rust_layer_traces(args: &LayerTraceRustCaptureArgs) -> Result<Value> {
    let plan_path = normalize_path(&args.plan)?;
    let cpu_trace_dir = normalize_path(&args.cpu_trace_dir)?;
    let a770_trace_dir = normalize_path(&args.a770_trace_dir)?;
    let plan_result = read_json(&plan_path);
    let plan_read_success = plan_result.is_ok();
    let plan = plan_result.unwrap_or(Value::Null);

    let (cpu_argv, cpu_command_key) = if plan_read_success {
        preferred_rust_trace_argv(&plan, "cpu_first_token_logit_argv", "cpu_argv")
    } else {
        (None, None)
    };
    let (a770_argv, a770_command_key) = if plan_read_success {
        preferred_rust_trace_argv(&plan, "a770_first_token_logit_argv", "a770_argv")
    } else {
        (None, None)
    };
    let (cpu_argv, cpu_trace_feature_injected) =
        cpu_argv.map(|argv| ensure_trace_feature(&argv)).unzip();
    let (a770_argv, a770_trace_feature_injected) =
        a770_argv.map(|argv| ensure_trace_feature(&argv)).unzip();
    let trace_target_seq =
        if plan_read_success { rust_trace_target_seq_from_plan(&plan) } else { None };

    let mut blocked_reasons = Vec::<String>::new();
    if !plan_path.is_file() {
        blocked_reasons.push("reference_plan_missing".to_string());
    } else if !plan_read_success {
        blocked_reasons.push("reference_plan_json_invalid".to_string());
    }
    if plan_read_success && cpu_argv.is_none() {
        blocked_reasons.push("rust_cpu_trace_command_missing".to_string());
    }
    if plan_read_success && !args.skip_a770 && a770_argv.is_none() {
        blocked_reasons.push("strict_a770_trace_command_missing".to_string());
    }

    let cpu_prepare = prepare_trace_dir(&cpu_trace_dir, args.overwrite)?;
    if let Some(reason) = cpu_prepare.pointer("/blocked_reason").and_then(Value::as_str) {
        blocked_reasons.push(format!("cpu_trace_dir_{reason}"));
    }
    let a770_prepare = if args.skip_a770 {
        json!({
            "trace_dir": path_to_string(&a770_trace_dir),
            "skipped": true,
            "reason": "skip_a770_requested",
        })
    } else {
        let prepare = prepare_trace_dir(&a770_trace_dir, args.overwrite)?;
        if let Some(reason) = prepare.pointer("/blocked_reason").and_then(Value::as_str) {
            blocked_reasons.push(format!("strict_a770_trace_dir_{reason}"));
        }
        prepare
    };

    let can_run_cpu = blocked_reasons.is_empty();
    let cpu = if can_run_cpu {
        run_rust_trace_capture(
            "cpu",
            cpu_argv.as_deref().unwrap_or(&[]),
            &cpu_trace_dir,
            trace_target_seq,
            args.trace_layer,
            args.first_values_limit,
            args.diag_rmsnorm_f64_accum,
        )?
    } else {
        skipped_rust_trace_capture("cpu", cpu_argv.as_deref(), &cpu_trace_dir)
    };

    let can_run_a770 = blocked_reasons.is_empty() && !args.skip_a770;
    let a770 = if can_run_a770 {
        run_rust_trace_capture(
            "strict_a770",
            a770_argv.as_deref().unwrap_or(&[]),
            &a770_trace_dir,
            trace_target_seq,
            args.trace_layer,
            args.first_values_limit,
            args.diag_rmsnorm_f64_accum,
        )?
    } else {
        if args.skip_a770 {
            blocked_reasons.push("strict_a770_trace_capture_skipped".to_string());
        }
        skipped_rust_trace_capture("strict_a770", a770_argv.as_deref(), &a770_trace_dir)
    };

    append_trace_capture_blockers("cpu", &cpu, &mut blocked_reasons);
    if !args.skip_a770 {
        append_trace_capture_blockers("strict_a770", &a770, &mut blocked_reasons);
    }
    blocked_reasons.sort_unstable();
    blocked_reasons.dedup();

    let cpu_records = cpu.pointer("/trace/record_count").and_then(Value::as_u64).unwrap_or(0);
    let a770_records = a770.pointer("/trace/record_count").and_then(Value::as_u64).unwrap_or(0);
    let rust_layer_traces_ready = cpu_records > 0 && (args.skip_a770 || a770_records > 0);
    let compare_ready = cpu_records > 0 && !args.skip_a770 && a770_records > 0;

    Ok(json!({
        "schema_version": 1,
        "receipt_type": "bitnet_reference_layer_trace_rust_capture",
        "diagnostic": "bitnet_reference_layer_trace_rust_capture",
        "producer": "cargo xtask bitnet-reference-layer-trace-capture-rust",
        "created_at": chrono::Utc::now().to_rfc3339(),
        "diagnostic_only": true,
        "promotion_allowed": false,
        "claim_allowed": false,
        "classification": "diagnostic_only",
        "inputs": {
            "plan": path_to_string(&plan_path),
            "cpu_trace_dir": path_to_string(&cpu_trace_dir),
            "a770_trace_dir": path_to_string(&a770_trace_dir),
            "skip_a770": args.skip_a770,
            "diag_rmsnorm_f64_accum": args.diag_rmsnorm_f64_accum,
            "trace_layer": args.trace_layer,
            "first_values_limit": args.first_values_limit,
            "overwrite": args.overwrite,
        },
        "model": plan.pointer("/model").cloned().unwrap_or(Value::Null),
        "prompt_identity": plan.pointer("/prompt_identity").cloned().unwrap_or(Value::Null),
        "proof_identity": plan.pointer("/rust_commands/proof_identity").cloned().unwrap_or(Value::Null),
        "preflight": {
            "plan_exists": plan_path.is_file(),
            "plan_json_valid": plan_read_success,
            "cpu_command_present": cpu_argv.is_some(),
            "a770_command_present": a770_argv.is_some(),
            "cpu_command_key": cpu_command_key,
            "a770_command_key": a770_command_key,
            "trace_target_seq": trace_target_seq,
            "trace_target_source": trace_target_seq.map(|_| "prompt_identity.prompt_token_count_minus_one"),
            "trace_layer": args.trace_layer,
            "trace_layer_source": args.trace_layer.map(|_| "--trace-layer"),
            "cpu_trace_feature_injected": cpu_trace_feature_injected.unwrap_or(false),
            "a770_trace_feature_injected": a770_trace_feature_injected.unwrap_or(false),
            "diag_rmsnorm_f64_accum": args.diag_rmsnorm_f64_accum,
            "diag_rmsnorm_f64_accum_env": args
                .diag_rmsnorm_f64_accum
                .then_some("BITNET_DIAG_RMSNORM_F64_ACCUM=1"),
            "cpu_trace_dir_prepare": cpu_prepare,
            "a770_trace_dir_prepare": a770_prepare,
            "first_values_limit_env": std::env::var("BITNET_TRACE_FIRST_VALUES_LIMIT").ok(),
            "first_values_limit_arg": args.first_values_limit,
            "first_values_limit_effective": args
                .first_values_limit
                .or_else(|| std::env::var("BITNET_TRACE_FIRST_VALUES_LIMIT").ok().and_then(|value| value.parse().ok())),
        },
        "cpu": cpu,
        "a770": a770,
        "decision": {
            "rust_layer_traces_ready": rust_layer_traces_ready,
            "compare_ready": compare_ready,
            "claim_allowed": false,
            "current_blocked_reasons": blocked_reasons,
            "next_when_ready": "run bitnet-reference-layer-trace-compare with the reference run receipt plus the captured CPU and strict A770 trace directories",
        },
        "not_claims": CRITICAL_NOT_CLAIMS,
    }))
}

fn build_embedding_row_authority(args: &EmbeddingRowAuthorityArgs) -> Result<Value> {
    let reference_path = normalize_path(&args.reference)?;
    let reference_root = read_json(&reference_path)?;
    let trace = reference_trace_receipt(&reference_root)?;
    let model_path = args
        .model
        .clone()
        .or_else(|| {
            reference_root.pointer("/model/model_path").and_then(Value::as_str).map(PathBuf::from)
        })
        .unwrap_or_else(|| PathBuf::from(DEFAULT_BITNET_MODEL));
    let model_path = normalize_path(&model_path)?;

    let token_ids = reference_prompt_tokens(trace);
    let sampled_output_token_id = trace.pointer("/sampled_output_token_id").and_then(Value::as_u64);
    let sampled_output_token_index =
        trace.pointer("/sampled_output_token_index").and_then(Value::as_i64);
    let inp_embd = trace.pointer("/records").and_then(Value::as_array).and_then(|records| {
        records
            .iter()
            .find(|record| record.pointer("/stage").and_then(Value::as_str) == Some("inp_embd"))
    });
    let expected_width = inp_embd
        .and_then(|record| record.pointer("/nelements").and_then(Value::as_u64))
        .unwrap_or(0) as usize;
    let reference_first_values = inp_embd
        .and_then(|record| record.pointer("/first_values").and_then(Value::as_array))
        .map(|values| {
            values.iter().filter_map(Value::as_f64).map(|value| value as f32).collect::<Vec<_>>()
        })
        .unwrap_or_default();

    let mut blocked_reasons = Vec::<String>::new();
    if !reference_path.is_file() {
        blocked_reasons.push("reference_layer_trace_receipt_missing".to_string());
    }
    if !model_path.is_file() {
        blocked_reasons.push("model_gguf_missing".to_string());
    }
    if token_ids.is_empty() {
        blocked_reasons.push("reference_trace_prompt_tokens_missing".to_string());
    }
    if expected_width == 0 {
        blocked_reasons.push("reference_inp_embd_width_missing".to_string());
    }

    let mut model = json!({
        "path": path_to_string(&model_path),
        "exists": model_path.is_file(),
    });
    let mut tensor = Value::Null;
    let mut rows = Vec::<Value>::new();

    if model_path.is_file() && !token_ids.is_empty() && expected_width > 0 {
        match build_embedding_row_authority_rows(
            &model_path,
            &token_ids,
            sampled_output_token_index,
            sampled_output_token_id,
            expected_width,
            &reference_first_values,
        ) {
            Ok((model_report, tensor_report, row_reports)) => {
                model = model_report;
                tensor = tensor_report;
                rows = row_reports;
            }
            Err(err) => {
                blocked_reasons.push(format!("embedding_row_authority_unavailable:{err}"));
            }
        }
    }

    let sampled_row = rows
        .iter()
        .find(|row| {
            if let Some(index) = sampled_output_token_index {
                row.pointer("/prompt_index").and_then(Value::as_i64) == Some(index)
            } else {
                sampled_output_token_id.is_some_and(|token_id| {
                    row.pointer("/token_id").and_then(Value::as_u64) == Some(token_id)
                })
            }
        })
        .cloned();
    let reference_row_matches_trace_sample = sampled_row.as_ref().is_some_and(|row| {
        row_candidate_delta_le(row, "/reference_raw_vs_trace_first_values/max_abs_delta", 1.0e-3)
    });
    let rust_loaded_matches_reference_row = sampled_row.as_ref().is_some_and(|row| {
        row_candidate_delta_le(row, "/reference_raw_vs_rust_loaded/max_abs_delta", 1.0e-3)
    });
    let reference_trace_matching_layouts = sampled_row
        .as_ref()
        .map(|row| {
            row_candidate_matching_layouts(
                row,
                "/reference_raw_vs_trace_first_values/max_abs_delta",
                1.0e-3,
            )
        })
        .unwrap_or_default();
    let rust_loaded_matching_layouts = sampled_row
        .as_ref()
        .map(|row| {
            row_candidate_matching_layouts(
                row,
                "/reference_raw_vs_rust_loaded/max_abs_delta",
                1.0e-3,
            )
        })
        .unwrap_or_default();
    let shared_matching_layouts = reference_trace_matching_layouts
        .iter()
        .filter(|layout| rust_loaded_matching_layouts.contains(layout))
        .cloned()
        .collect::<Vec<_>>();
    let layout_authority_aligned = !shared_matching_layouts.is_empty();

    let input_authority_ready = blocked_reasons.is_empty() && sampled_row.is_some();
    let mut current_blocked_reasons = blocked_reasons.clone();
    if input_authority_ready
        && reference_row_matches_trace_sample
        && rust_loaded_matches_reference_row
        && !layout_authority_aligned
    {
        current_blocked_reasons
            .push("embedding_reference_and_rust_layout_authority_split".to_string());
    }

    let authority_ready = input_authority_ready && layout_authority_aligned;
    let next_action = if !input_authority_ready {
        "make the reference trace, prompt token ids, and GGUF model path available"
    } else if reference_row_matches_trace_sample
        && rust_loaded_matches_reference_row
        && !layout_authority_aligned
    {
        "inspect Rust embedding layout/transpose handling; reference trace and Rust-loaded embeddings match different raw layout candidates"
    } else if reference_row_matches_trace_sample && !rust_loaded_matches_reference_row {
        "inspect Rust GGUF embedding normalization or transformer handoff before changing downstream math"
    } else if rust_loaded_matches_reference_row && !reference_row_matches_trace_sample {
        "repair reference trace value capture for early graph nodes; raw GGUF and Rust-loaded embedding rows agree, but sampled trace values do not match token_embd.weight"
    } else if !reference_row_matches_trace_sample {
        "inspect reference trace sampling or token_embd raw row interpretation before changing Rust model math"
    } else {
        "embedding row authority matches; move the first-divergence search past prompt embedding"
    };

    Ok(json!({
        "schema_version": 1,
        "receipt_type": "bitnet_reference_embedding_row_authority",
        "diagnostic": "bitnet_reference_embedding_row_authority",
        "producer": "cargo xtask bitnet-reference-embedding-row-authority",
        "created_at": chrono::Utc::now().to_rfc3339(),
        "diagnostic_only": true,
        "claim_allowed": false,
        "promotion_allowed": false,
        "classification": "diagnostic_only",
        "inputs": {
            "reference": path_to_string(&reference_path),
            "model": path_to_string(&model_path),
        },
        "reference_trace": {
            "capture_scope": trace.pointer("/capture_scope").cloned().unwrap_or(Value::Null),
            "warmup_skip_policy": trace.pointer("/warmup_skip_policy").cloned().unwrap_or(Value::Null),
            "n_tokens": trace.pointer("/n_tokens").cloned().unwrap_or(Value::Null),
            "n_outputs": trace.pointer("/n_outputs").cloned().unwrap_or(Value::Null),
            "sampled_output_token_index": sampled_output_token_index,
            "sampled_output_token_id": sampled_output_token_id,
            "prompt_token_count": token_ids.len(),
            "prompt_token_ids": token_ids,
            "inp_embd": inp_embd.map(reference_inp_embd_summary).unwrap_or(Value::Null),
        },
        "model": model,
        "embedding_tensor": tensor,
        "rows": rows,
        "decision": {
            "embedding_row_authority_ready": authority_ready,
            "embedding_row_authority_inputs_ready": input_authority_ready,
            "reference_row_matches_trace_sample": reference_row_matches_trace_sample,
            "rust_loaded_matches_reference_row": rust_loaded_matches_reference_row,
            "reference_trace_matching_layouts": reference_trace_matching_layouts,
            "rust_loaded_matching_layouts": rust_loaded_matching_layouts,
            "shared_matching_layouts": shared_matching_layouts,
            "layout_authority_aligned": layout_authority_aligned,
            "current_blocked_reasons": current_blocked_reasons,
            "next_action": next_action,
            "claim_allowed": false,
        },
        "not_claims": CRITICAL_NOT_CLAIMS,
    }))
}

fn build_attn_output_same_input_parity(args: &AttnOutputSameInputArgs) -> Result<Value> {
    let reference_path = normalize_path(&args.reference)?;
    let reference_root = read_json(&reference_path)?;
    let reference_records = read_reference_records(&reference_root)?;
    let trace = reference_trace_receipt(&reference_root)?;
    let model_path = args
        .model
        .clone()
        .or_else(|| {
            reference_root.pointer("/model/model_path").and_then(Value::as_str).map(PathBuf::from)
        })
        .unwrap_or_else(|| PathBuf::from(DEFAULT_BITNET_MODEL));
    let model_path = normalize_path(&model_path)?;
    let weight_layer = layer_index_from_blk_weight(&args.weight);
    let layer = args.layer.or(weight_layer).unwrap_or(0);
    let layer_source = if args.layer.is_some() {
        "--layer"
    } else if weight_layer.is_some() {
        "weight_name"
    } else {
        "default_layer0"
    };

    let input = find_reference_trace_record(&reference_records, "attn_sub_norm", Some(layer));
    let target = find_reference_trace_record(&reference_records, "attn_o_out", Some(layer));

    let mut blocked_reasons = Vec::<String>::new();
    if !reference_path.is_file() {
        blocked_reasons.push("reference_layer_trace_receipt_missing".to_string());
    }
    if !model_path.is_file() {
        blocked_reasons.push("model_gguf_missing".to_string());
    }
    if args.layer.is_some() && weight_layer.is_some() && args.layer != weight_layer {
        blocked_reasons.push(format!(
            "attn_output_same_input_layer_mismatch:requested_layer{}_weight_layer{}",
            layer,
            weight_layer.expect("checked above")
        ));
    }
    if input.is_none() {
        blocked_reasons.push(format!("reference_attn_sub_norm_layer{layer}_missing"));
    }
    if target.is_none() {
        blocked_reasons.push(format!("reference_attn_o_out_layer{layer}_missing"));
    }

    let input_count = input.map(|record| record.first_values.len()).unwrap_or(0);
    let target_count = target.map(|record| record.first_values.len()).unwrap_or(0);
    if input_count == 0 {
        blocked_reasons.push("reference_attn_sub_norm_first_values_missing".to_string());
    }
    if target_count == 0 {
        blocked_reasons.push("reference_attn_o_out_first_values_missing".to_string());
    }

    let mut model = json!({
        "path": path_to_string(&model_path),
        "exists": model_path.is_file(),
    });
    let mut weight = json!({
        "name": args.weight,
    });
    let mut projection = Value::Null;

    if blocked_reasons.is_empty() {
        let input = input.expect("checked above");
        let target = target.expect("checked above");
        match project_qk256_same_input(
            &model_path,
            &args.weight,
            &input.first_values,
            Some(target.first_values.len()),
        ) {
            Ok((model_report, weight_report, output)) => {
                model = model_report;
                weight = weight_report;
                let comparison = compare_prefix(
                    &output,
                    &target.first_values,
                    output.len().min(target.first_values.len()),
                );
                projection = json!({
                    "kernel": "rust_qk256_activation_quantized_scaled_same_input_cpu_oracle",
                    "layer": layer,
                    "input_stage": "attn_sub_norm",
                    "target_stage": "attn_o_out",
                    "input": row_report(&input.first_values),
                    "rust_same_input_output": row_report(&output),
                    "reference_target": row_report(&target.first_values),
                    "rust_same_input_vs_reference_target": comparison,
                });
            }
            Err(err) => {
                blocked_reasons
                    .push(format!("attn_output_same_input_projection_unavailable:{err}"));
            }
        }
    }

    let same_input_projection_available =
        projection.pointer("/rust_same_input_vs_reference_target").is_some();
    let same_input_projection_matches_reference = projection
        .pointer("/rust_same_input_vs_reference_target/max_abs_delta")
        .and_then(Value::as_f64)
        .is_some_and(|delta| delta <= 1.0e-3);
    let current_blocked_reasons = if blocked_reasons.is_empty() {
        if same_input_projection_matches_reference {
            vec![
                "same_input_attn_output_projection_match_does_not_explain_upstream_delta"
                    .to_string(),
            ]
        } else {
            vec!["same_input_attn_output_projection_mismatch".to_string()]
        }
    } else {
        blocked_reasons.clone()
    };
    let next_action = if !blocked_reasons.is_empty() {
        "regenerate full-prefix reference layer traces and ensure the model path is available"
    } else if same_input_projection_matches_reference {
        "treat attn_output projection math/layout as same-input compatible; localize the upstream attn_sub_norm input delta"
    } else {
        "inspect Rust QK256 attn_output weight layout, scale, and activation quantization before changing broader runtime math"
    };

    Ok(json!({
        "schema_version": 1,
        "receipt_type": "bitnet_reference_attn_output_same_input_parity",
        "diagnostic": "bitnet_reference_attn_output_same_input_parity",
        "producer": "cargo xtask bitnet-reference-attn-output-same-input-parity",
        "created_at": chrono::Utc::now().to_rfc3339(),
        "diagnostic_only": true,
        "claim_allowed": false,
        "promotion_allowed": false,
        "classification": "diagnostic_only",
        "inputs": {
            "reference": path_to_string(&reference_path),
            "model": path_to_string(&model_path),
            "weight": args.weight,
            "requested_layer": args.layer,
            "inferred_weight_layer": weight_layer,
            "selected_layer": layer,
            "layer_source": layer_source,
        },
        "reference_trace": {
            "capture_scope": trace.pointer("/capture_scope").cloned().unwrap_or(Value::Null),
            "warmup_skip_policy": trace.pointer("/warmup_skip_policy").cloned().unwrap_or(Value::Null),
            "n_tokens": trace.pointer("/n_tokens").cloned().unwrap_or(Value::Null),
            "n_outputs": trace.pointer("/n_outputs").cloned().unwrap_or(Value::Null),
            "sampled_output_token_index": trace.pointer("/sampled_output_token_index").cloned().unwrap_or(Value::Null),
            "sampled_output_token_id": trace.pointer("/sampled_output_token_id").cloned().unwrap_or(Value::Null),
            "attn_sub_norm": input.map(reference_record_summary).unwrap_or(Value::Null),
            "attn_o_out": target.map(reference_record_summary).unwrap_or(Value::Null),
        },
        "model": model,
        "weight": weight,
        "projection": projection,
        "decision": {
            "same_input_projection_available": same_input_projection_available,
            "same_input_projection_matches_reference": same_input_projection_matches_reference,
            "selected_layer": layer,
            "input_first_values_count": input_count,
            "target_first_values_count": target_count,
            "current_blocked_reasons": current_blocked_reasons,
            "next_action": next_action,
            "claim_allowed": false,
        },
        "not_claims": CRITICAL_NOT_CLAIMS,
    }))
}

fn build_value_projection_same_input_parity(args: &ValueProjectionSameInputArgs) -> Result<Value> {
    let reference_path = normalize_path(&args.reference)?;
    let reference_root = read_json(&reference_path)?;
    let reference_records = read_reference_records(&reference_root)?;
    let trace = reference_trace_receipt(&reference_root)?;
    let model_path = args
        .model
        .clone()
        .or_else(|| {
            reference_root.pointer("/model/model_path").and_then(Value::as_str).map(PathBuf::from)
        })
        .unwrap_or_else(|| PathBuf::from(DEFAULT_BITNET_MODEL));
    let model_path = normalize_path(&model_path)?;

    let input = reference_records
        .iter()
        .find(|record| record.stage == "attn_norm" && record.layer == Some(0));
    let target =
        reference_records.iter().find(|record| record.stage == "Vcur" && record.layer == Some(0));

    let mut blocked_reasons = Vec::<String>::new();
    if !reference_path.is_file() {
        blocked_reasons.push("reference_layer_trace_receipt_missing".to_string());
    }
    if !model_path.is_file() {
        blocked_reasons.push("model_gguf_missing".to_string());
    }
    if input.is_none() {
        blocked_reasons.push("reference_attn_norm_layer0_missing".to_string());
    }
    if target.is_none() {
        blocked_reasons.push("reference_vcur_layer0_missing".to_string());
    }

    let input_count = input.map(|record| record.first_values.len()).unwrap_or(0);
    let target_count = target.map(|record| record.first_values.len()).unwrap_or(0);
    if input_count == 0 {
        blocked_reasons.push("reference_attn_norm_first_values_missing".to_string());
    }
    if target_count == 0 {
        blocked_reasons.push("reference_vcur_first_values_missing".to_string());
    }

    let mut model = json!({
        "path": path_to_string(&model_path),
        "exists": model_path.is_file(),
    });
    let mut weight = json!({
        "name": args.weight,
    });
    let mut projection = Value::Null;

    if blocked_reasons.is_empty() {
        let input = input.expect("checked above");
        let target = target.expect("checked above");
        match project_qk256_same_input(
            &model_path,
            &args.weight,
            &input.first_values,
            Some(target.first_values.len()),
        ) {
            Ok((model_report, weight_report, output)) => {
                model = model_report;
                weight = weight_report;
                let comparison = compare_prefix(
                    &output,
                    &target.first_values,
                    output.len().min(target.first_values.len()),
                );
                projection = json!({
                    "kernel": "rust_qk256_activation_quantized_scaled_same_input_cpu_oracle",
                    "input_stage": "attn_norm",
                    "target_stage": "Vcur",
                    "input": row_report(&input.first_values),
                    "rust_same_input_output": row_report(&output),
                    "reference_target": row_report(&target.first_values),
                    "rust_same_input_vs_reference_target": comparison,
                });
            }
            Err(err) => {
                blocked_reasons
                    .push(format!("value_projection_same_input_projection_unavailable:{err}"));
            }
        }
    }

    let same_input_projection_available =
        projection.pointer("/rust_same_input_vs_reference_target").is_some();
    let same_input_projection_matches_reference = projection
        .pointer("/rust_same_input_vs_reference_target/max_abs_delta")
        .and_then(Value::as_f64)
        .is_some_and(|delta| delta <= 1.0e-3);
    let current_blocked_reasons = if blocked_reasons.is_empty() {
        if same_input_projection_matches_reference {
            vec!["same_input_value_projection_match_does_not_explain_upstream_delta".to_string()]
        } else {
            vec!["same_input_value_projection_mismatch".to_string()]
        }
    } else {
        blocked_reasons.clone()
    };
    let next_action = if !blocked_reasons.is_empty() {
        "regenerate full-prefix reference layer traces and ensure the model path is available"
    } else if same_input_projection_matches_reference {
        "treat value projection math/layout as same-input compatible; localize the upstream attn_norm input delta"
    } else {
        "inspect Rust QK256 value-projection weight layout, scale, and activation quantization before changing cache or value-mix math"
    };

    Ok(json!({
        "schema_version": 1,
        "receipt_type": "bitnet_reference_value_projection_same_input_parity",
        "diagnostic": "bitnet_reference_value_projection_same_input_parity",
        "producer": "cargo xtask bitnet-reference-value-projection-same-input-parity",
        "created_at": chrono::Utc::now().to_rfc3339(),
        "diagnostic_only": true,
        "claim_allowed": false,
        "promotion_allowed": false,
        "classification": "diagnostic_only",
        "inputs": {
            "reference": path_to_string(&reference_path),
            "model": path_to_string(&model_path),
            "weight": args.weight,
        },
        "reference_trace": {
            "capture_scope": trace.pointer("/capture_scope").cloned().unwrap_or(Value::Null),
            "warmup_skip_policy": trace.pointer("/warmup_skip_policy").cloned().unwrap_or(Value::Null),
            "n_tokens": trace.pointer("/n_tokens").cloned().unwrap_or(Value::Null),
            "n_outputs": trace.pointer("/n_outputs").cloned().unwrap_or(Value::Null),
            "sampled_output_token_index": trace.pointer("/sampled_output_token_index").cloned().unwrap_or(Value::Null),
            "sampled_output_token_id": trace.pointer("/sampled_output_token_id").cloned().unwrap_or(Value::Null),
            "attn_norm": input.map(reference_record_summary).unwrap_or(Value::Null),
            "Vcur": target.map(reference_record_summary).unwrap_or(Value::Null),
        },
        "model": model,
        "weight": weight,
        "projection": projection,
        "decision": {
            "same_input_projection_available": same_input_projection_available,
            "same_input_projection_matches_reference": same_input_projection_matches_reference,
            "input_first_values_count": input_count,
            "target_first_values_count": target_count,
            "current_blocked_reasons": current_blocked_reasons,
            "next_action": next_action,
            "claim_allowed": false,
        },
        "not_claims": CRITICAL_NOT_CLAIMS,
    }))
}

fn build_value_projection_history_replay(args: &ValueProjectionHistoryReplayArgs) -> Result<Value> {
    let reference_path = normalize_path(&args.reference)?;
    let cpu_trace_dir = normalize_path(&args.cpu_trace_dir)?;
    let reference_root = read_json(&reference_path)?;
    let reference_records = read_reference_records(&reference_root)?;
    let trace = reference_trace_receipt(&reference_root)?;
    let model_path = args
        .model
        .clone()
        .or_else(|| {
            reference_root.pointer("/model/model_path").and_then(Value::as_str).map(PathBuf::from)
        })
        .unwrap_or_else(|| PathBuf::from(DEFAULT_BITNET_MODEL));
    let model_path = normalize_path(&model_path)?;

    let rust_records = read_rust_trace_dir(&cpu_trace_dir).ok();
    let reference_input =
        reference_records.iter().find(|record| record.stage == "attn_norm_history_ref_layout");
    let reference_target =
        reference_records.iter().find(|record| record.stage == "vcur_history_ref_layout");
    let reference_current_input = reference_records
        .iter()
        .find(|record| record.stage == "attn_norm" && record.layer == Some(0));
    let reference_current_target =
        reference_records.iter().find(|record| record.stage == "Vcur" && record.layer == Some(0));
    let rust_input = rust_records
        .as_ref()
        .and_then(|records| records.get("attention_v_input_history_ref_layout"));
    let rust_target = rust_records
        .as_ref()
        .and_then(|records| collect_rust_value_before_cache_history(records).ok());

    let mut blocked_reasons = Vec::<String>::new();
    if !reference_path.is_file() {
        blocked_reasons.push("reference_layer_trace_receipt_missing".to_string());
    }
    if !model_path.is_file() {
        blocked_reasons.push("model_gguf_missing".to_string());
    }
    if reference_input.is_none() {
        blocked_reasons.push("reference_attn_norm_history_ref_layout_missing".to_string());
    }
    if reference_target.is_none() {
        blocked_reasons.push("reference_vcur_history_ref_layout_missing".to_string());
    }
    if rust_records.is_none() {
        blocked_reasons.push("rust_cpu_trace_dir_unavailable".to_string());
    }
    if rust_input.is_none() {
        blocked_reasons.push("rust_attention_v_input_history_ref_layout_missing".to_string());
    }
    if rust_target.is_none() {
        blocked_reasons.push("rust_attention_v_before_cache_store_history_unavailable".to_string());
    }

    let mut model = json!({
        "path": path_to_string(&model_path),
        "exists": model_path.is_file(),
    });
    let mut weight = json!({
        "name": args.weight,
    });
    let mut replay = Value::Null;

    if model_path.is_file() && reference_input.is_some() && reference_target.is_some() {
        let reference_input = reference_input.expect("checked above");
        let reference_target = reference_target.expect("checked above");
        match build_value_projection_history_replay_body(
            &model_path,
            &args.weight,
            reference_input,
            reference_target,
            rust_input,
            rust_target.as_ref(),
            reference_current_input,
            reference_current_target,
        ) {
            Ok((model_report, weight_report, replay_report)) => {
                model = model_report;
                weight = weight_report;
                replay = replay_report;
            }
            Err(err) => {
                blocked_reasons.push(format!("value_projection_history_replay_unavailable:{err}"));
            }
        }
    }

    let reference_replay_matches = replay
        .pointer("/reference_history_replay/rust_replay_vs_reference_target/max_abs_delta")
        .and_then(Value::as_f64)
        .is_some_and(|delta| delta <= 1.0e-3);
    let rust_replay_matches_runtime = replay
        .pointer("/rust_history_replay/rust_replay_vs_rust_trace/max_abs_delta")
        .and_then(Value::as_f64)
        .is_some_and(|delta| delta <= 1.0e-3);
    let rust_replay_bucket_mismatches_reference = replay
        .pointer("/rust_history_replay/rust_replay_vs_reference_target/f16_bucket_mismatch_count")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let input_history_materially_same = replay
        .pointer("/input_history/reference_vs_rust/max_abs_delta")
        .and_then(Value::as_f64)
        .is_some_and(|delta| delta <= 1.0e-6);
    let current_token_history_consistent = replay
        .pointer("/current_token_replay/current_input_vs_history_token/max_abs_delta")
        .and_then(Value::as_f64)
        .is_some_and(|delta| delta <= 1.0e-6)
        && replay
            .pointer("/current_token_replay/current_replay_vs_history_replay_token/max_abs_delta")
            .and_then(Value::as_f64)
            .is_some_and(|delta| delta <= 1.0e-3);
    let current_token_history_consistency_applicable = replay
        .pointer("/current_token_replay/consistency_applicable")
        .and_then(Value::as_bool)
        .unwrap_or(false);

    let current_blocked_reasons = if blocked_reasons.is_empty() {
        classify_value_projection_history_replay(
            reference_replay_matches,
            rust_replay_matches_runtime,
            rust_replay_bucket_mismatches_reference,
            input_history_materially_same,
            current_token_history_consistency_applicable,
            current_token_history_consistent,
        )
    } else {
        blocked_reasons.clone()
    };
    let next_action = value_projection_history_replay_next_action(&current_blocked_reasons);

    Ok(json!({
        "schema_version": 1,
        "receipt_type": "bitnet_reference_value_projection_history_replay",
        "diagnostic": "bitnet_reference_value_projection_history_replay",
        "producer": "cargo xtask bitnet-reference-value-projection-history-replay",
        "created_at": chrono::Utc::now().to_rfc3339(),
        "diagnostic_only": true,
        "claim_allowed": false,
        "promotion_allowed": false,
        "classification": "diagnostic_only",
        "inputs": {
            "reference": path_to_string(&reference_path),
            "cpu_trace_dir": path_to_string(&cpu_trace_dir),
            "model": path_to_string(&model_path),
            "weight": args.weight,
        },
        "reference_trace": {
            "capture_scope": trace.pointer("/capture_scope").cloned().unwrap_or(Value::Null),
            "warmup_skip_policy": trace.pointer("/warmup_skip_policy").cloned().unwrap_or(Value::Null),
            "n_tokens": trace.pointer("/n_tokens").cloned().unwrap_or(Value::Null),
            "n_outputs": trace.pointer("/n_outputs").cloned().unwrap_or(Value::Null),
            "sampled_output_token_index": trace.pointer("/sampled_output_token_index").cloned().unwrap_or(Value::Null),
            "sampled_output_token_id": trace.pointer("/sampled_output_token_id").cloned().unwrap_or(Value::Null),
            "attn_norm_history_ref_layout": reference_input.map(reference_record_summary).unwrap_or(Value::Null),
            "vcur_history_ref_layout": reference_target.map(reference_record_summary).unwrap_or(Value::Null),
        },
        "rust_trace": {
            "present": rust_records.is_some(),
            "attention_v_input_history_ref_layout": rust_input.map(rust_record_summary).unwrap_or(Value::Null),
            "attention_v_before_cache_store_history": rust_target.as_ref().map(rust_value_history_summary).unwrap_or(Value::Null),
        },
        "model": model,
        "weight": weight,
        "replay": replay,
        "decision": {
            "reference_history_replay_matches_reference": reference_replay_matches,
            "rust_history_replay_matches_rust_trace": rust_replay_matches_runtime,
            "rust_history_replay_reference_f16_bucket_mismatch_count": rust_replay_bucket_mismatches_reference,
            "input_history_materially_same": input_history_materially_same,
            "current_token_history_consistency_applicable": current_token_history_consistency_applicable,
            "current_token_history_consistent": current_token_history_consistent,
            "current_blocked_reasons": current_blocked_reasons,
            "next_action": next_action,
            "claim_allowed": false,
        },
        "not_claims": CRITICAL_NOT_CLAIMS,
    }))
}

fn build_ffn_projection_history_replay(args: &FfnProjectionHistoryReplayArgs) -> Result<Value> {
    let reference_path = normalize_path(&args.reference)?;
    let cpu_trace_dir = normalize_path(&args.cpu_trace_dir)?;
    let reference_root = read_json(&reference_path)?;
    let reference_records = read_reference_records(&reference_root)?;
    let trace = reference_trace_receipt(&reference_root)?;
    let model_path = args
        .model
        .clone()
        .or_else(|| {
            reference_root.pointer("/model/model_path").and_then(Value::as_str).map(PathBuf::from)
        })
        .unwrap_or_else(|| PathBuf::from(DEFAULT_BITNET_MODEL));
    let model_path = normalize_path(&model_path)?;

    let rust_record_list = read_rust_trace_records(&cpu_trace_dir).ok();
    let reference_input = find_reference_trace_record(
        &reference_records,
        "ffn_norm_history_ref_layout",
        Some(args.layer),
    );
    let rust_input = rust_record_list.as_ref().and_then(|records| {
        find_rust_trace_record(records, "post_ffn_norm_history_ref_layout", Some(args.layer))
    });

    let mut blocked_reasons = Vec::<String>::new();
    if !reference_path.is_file() {
        blocked_reasons.push("reference_layer_trace_receipt_missing".to_string());
    }
    if !model_path.is_file() {
        blocked_reasons.push("model_gguf_missing".to_string());
    }
    if reference_input.is_none() {
        blocked_reasons.push("reference_ffn_norm_history_ref_layout_missing".to_string());
    }
    if rust_record_list.is_none() {
        blocked_reasons.push("rust_cpu_trace_dir_unavailable".to_string());
    }
    if rust_input.is_none() {
        blocked_reasons.push("rust_post_ffn_norm_history_ref_layout_missing".to_string());
    }

    let mut rows = Vec::<Value>::new();
    let mut row_failures = Vec::<String>::new();
    if model_path.is_file() && reference_input.is_some() {
        let reference_input = reference_input.expect("checked above");
        for spec in [
            FfnProjectionReplaySpec {
                projection: "up",
                weight_name: format!("blk.{}.ffn_up.weight", args.layer),
                reference_target_stage: "ffn_up_history_ref_layout",
                rust_target_stage: "post_ffn_up_proj_history_ref_layout",
            },
            FfnProjectionReplaySpec {
                projection: "gate",
                weight_name: format!("blk.{}.ffn_gate.weight", args.layer),
                reference_target_stage: "ffn_gate_history_ref_layout",
                rust_target_stage: "post_ffn_gate_proj_history_ref_layout",
            },
        ] {
            match build_ffn_projection_history_replay_row(
                &model_path,
                args.layer,
                reference_input,
                rust_input,
                &reference_records,
                rust_record_list.as_deref(),
                &spec,
            ) {
                Ok(row) => rows.push(row),
                Err(err) => {
                    row_failures.push(format!(
                        "{}_ffn_projection_history_replay_unavailable:{err}",
                        spec.projection
                    ));
                    rows.push(json!({
                        "projection": spec.projection,
                        "weight_name": spec.weight_name,
                        "reference_target_stage": spec.reference_target_stage,
                        "rust_target_stage": spec.rust_target_stage,
                        "status": "unavailable",
                        "error": err.to_string(),
                    }));
                }
            }
        }
    }
    blocked_reasons.extend(row_failures);

    let reference_replay_mismatch_count = rows
        .iter()
        .filter(|row| {
            !row.pointer("/decision/reference_replay_matches_reference")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        })
        .count();
    let rust_replay_mismatch_count = rows
        .iter()
        .filter(|row| {
            row.pointer("/decision/rust_replay_available").and_then(Value::as_bool).unwrap_or(false)
                && !row
                    .pointer("/decision/rust_replay_matches_rust_trace")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
        })
        .count();
    let reference_vs_rust_bucket_mismatch_count: u64 = rows
        .iter()
        .filter_map(|row| {
            row.pointer("/decision/rust_replay_reference_f16_bucket_mismatch_count")
                .and_then(Value::as_u64)
        })
        .sum();
    let input_history_materially_same = rows
        .iter()
        .filter_map(|row| {
            row.pointer("/decision/input_history_materially_same").and_then(Value::as_bool)
        })
        .all(|value| value)
        && rows.iter().any(|row| row.pointer("/decision/input_history_materially_same").is_some());

    let mut current_blocked_reasons = if blocked_reasons.is_empty() {
        classify_ffn_projection_history_replay(
            reference_replay_mismatch_count,
            rust_replay_mismatch_count,
            reference_vs_rust_bucket_mismatch_count,
            input_history_materially_same,
        )
    } else {
        blocked_reasons
    };
    current_blocked_reasons.sort_unstable();
    current_blocked_reasons.dedup();
    let next_action = ffn_projection_history_replay_next_action(&current_blocked_reasons);

    Ok(json!({
        "schema_version": 1,
        "receipt_type": "bitnet_reference_ffn_projection_history_replay",
        "diagnostic": "bitnet_reference_ffn_projection_history_replay",
        "producer": "cargo xtask bitnet-reference-ffn-projection-history-replay",
        "created_at": chrono::Utc::now().to_rfc3339(),
        "diagnostic_only": true,
        "claim_allowed": false,
        "promotion_allowed": false,
        "classification": "diagnostic_only",
        "inputs": {
            "reference": path_to_string(&reference_path),
            "cpu_trace_dir": path_to_string(&cpu_trace_dir),
            "model": path_to_string(&model_path),
            "layer": args.layer,
        },
        "reference_trace": {
            "capture_scope": trace.pointer("/capture_scope").cloned().unwrap_or(Value::Null),
            "n_tokens": trace.pointer("/n_tokens").cloned().unwrap_or(Value::Null),
            "sampled_output_token_index": trace.pointer("/sampled_output_token_index").cloned().unwrap_or(Value::Null),
            "ffn_norm_history_ref_layout": reference_input.map(reference_record_summary).unwrap_or(Value::Null),
        },
        "rust_trace": {
            "present": rust_record_list.is_some(),
            "post_ffn_norm_history_ref_layout": rust_input.map(rust_record_summary).unwrap_or(Value::Null),
        },
        "model": {
            "path": path_to_string(&model_path),
            "exists": model_path.is_file(),
        },
        "replay": {
            "kernel": "rust_qk256_activation_quantized_scaled_ffn_history_replay_cpu_oracle",
            "rows": rows,
        },
        "decision": {
            "reference_replay_mismatch_count": reference_replay_mismatch_count,
            "rust_replay_mismatch_count": rust_replay_mismatch_count,
            "rust_replay_reference_f16_bucket_mismatch_count": reference_vs_rust_bucket_mismatch_count,
            "input_history_materially_same": input_history_materially_same,
            "current_blocked_reasons": current_blocked_reasons,
            "next_action": next_action,
            "claim_allowed": false,
        },
        "not_claims": CRITICAL_NOT_CLAIMS,
    }))
}

struct FfnProjectionReplaySpec {
    projection: &'static str,
    weight_name: String,
    reference_target_stage: &'static str,
    rust_target_stage: &'static str,
}

fn build_ffn_projection_history_replay_row(
    model_path: &Path,
    layer: usize,
    reference_input: &ReferenceTraceRecord,
    rust_input: Option<&RustTraceRecord>,
    reference_records: &[ReferenceTraceRecord],
    rust_records: Option<&[RustTraceRecord]>,
    spec: &FfnProjectionReplaySpec,
) -> Result<Value> {
    let reference_target =
        find_reference_trace_record(reference_records, spec.reference_target_stage, Some(layer))
            .with_context(|| format!("reference {} missing", spec.reference_target_stage))?;
    let rust_target = rust_records
        .and_then(|records| find_rust_trace_record(records, spec.rust_target_stage, Some(layer)));

    let input_dim = dim_major_dim_count(reference_input)?;
    let token_count = dim_major_token_count(reference_input)?;
    let target_dim = dim_major_dim_count(reference_target)?;
    let target_token_count = dim_major_token_count(reference_target)?;
    if token_count != target_token_count {
        bail!(
            "reference input token_count {token_count} does not match {} token_count {target_token_count}",
            spec.reference_target_stage
        );
    }

    let projection = load_qk256_same_input_projection(
        model_path,
        &spec.weight_name,
        input_dim,
        Some(target_dim),
    )?;
    let reference_replay = replay_qk256_dim_major_history(
        &reference_input.first_values,
        input_dim,
        token_count,
        &projection,
    )?;
    let reference_delta = f16_bucket_delta_dim_major(
        &reference_replay,
        &reference_target.first_values,
        target_dim,
        token_count,
    );
    let input_history_delta = rust_input.map(|rust| {
        dim_major_token_value_delta(
            &reference_input.first_values,
            &rust.first_values,
            input_dim,
            token_count,
        )
    });
    let rust_replay = match rust_input {
        Some(rust) if !rust.first_values.is_empty() => Some(replay_qk256_dim_major_history(
            &rust.first_values,
            input_dim,
            token_count,
            &projection,
        )?),
        _ => None,
    };
    let rust_replay_vs_rust_trace =
        rust_replay.as_ref().zip(rust_target).map(|(replay, target)| {
            f16_bucket_delta_dim_major(replay, &target.first_values, target_dim, token_count)
        });
    let rust_replay_vs_reference_target = rust_replay.as_ref().map(|replay| {
        f16_bucket_delta_dim_major(replay, &reference_target.first_values, target_dim, token_count)
    });

    let reference_replay_matches_reference =
        delta_metric(&reference_delta, "/max_abs_delta") <= 1.0e-3;
    let rust_replay_matches_rust_trace = rust_replay_vs_rust_trace
        .as_ref()
        .is_some_and(|delta| delta_metric(delta, "/max_abs_delta") <= 1.0e-3);
    let input_history_materially_same = input_history_delta
        .as_ref()
        .is_some_and(|delta| delta_metric(delta, "/max_abs_delta") <= 1.0e-6);
    let rust_replay_reference_f16_bucket_mismatch_count = rust_replay_vs_reference_target
        .as_ref()
        .and_then(|delta| delta.pointer("/f16_bucket_mismatch_count").and_then(Value::as_u64))
        .unwrap_or(0);

    Ok(json!({
        "projection": spec.projection,
        "weight": projection.weight_report,
        "reference_target_stage": spec.reference_target_stage,
        "rust_target_stage": spec.rust_target_stage,
        "input_history": {
            "reference_stage": "ffn_norm_history_ref_layout",
            "rust_stage": "post_ffn_norm_history_ref_layout",
            "reference": row_report(&reference_input.first_values),
            "rust": rust_input.map(|record| row_report(&record.first_values)).unwrap_or(Value::Null),
            "reference_vs_rust": input_history_delta.unwrap_or(Value::Null),
        },
        "reference_history_replay": {
            "rust_replay": row_report(&reference_replay),
            "reference_target": row_report(&reference_target.first_values),
            "rust_replay_vs_reference_target": reference_delta,
        },
        "rust_history_replay": {
            "rust_replay": rust_replay.as_ref().map(|values| row_report(values)).unwrap_or(Value::Null),
            "rust_target": rust_target.map(rust_record_summary).unwrap_or(Value::Null),
            "rust_replay_vs_rust_trace": rust_replay_vs_rust_trace.unwrap_or(Value::Null),
            "rust_replay_vs_reference_target": rust_replay_vs_reference_target.unwrap_or(Value::Null),
        },
        "decision": {
            "reference_replay_matches_reference": reference_replay_matches_reference,
            "rust_replay_available": rust_replay.is_some(),
            "rust_replay_matches_rust_trace": rust_replay_matches_rust_trace,
            "input_history_materially_same": input_history_materially_same,
            "rust_replay_reference_f16_bucket_mismatch_count": rust_replay_reference_f16_bucket_mismatch_count,
            "claim_allowed": false,
        },
    }))
}

fn classify_ffn_projection_history_replay(
    reference_replay_mismatch_count: usize,
    rust_replay_mismatch_count: usize,
    reference_vs_rust_bucket_mismatch_count: u64,
    input_history_materially_same: bool,
) -> Vec<String> {
    if reference_replay_mismatch_count > 0 {
        vec!["reference_ffn_projection_replay_does_not_match_reference_target".to_string()]
    } else if rust_replay_mismatch_count > 0 {
        vec!["rust_ffn_projection_replay_does_not_match_rust_runtime".to_string()]
    } else if reference_vs_rust_bucket_mismatch_count > 0 && input_history_materially_same {
        vec!["tiny_ffn_norm_history_delta_amplified_by_qk256_activation_quantization".to_string()]
    } else if reference_vs_rust_bucket_mismatch_count > 0 {
        vec!["ffn_norm_history_delta_explains_ffn_projection_bucket_drift".to_string()]
    } else {
        vec!["ffn_projection_history_replay_no_longer_explains_ffn_drift".to_string()]
    }
}

fn ffn_projection_history_replay_next_action(reasons: &[String]) -> &'static str {
    if reasons
        .iter()
        .any(|reason| reason == "reference_ffn_projection_replay_does_not_match_reference_target")
    {
        "inspect QK256 FFN up/gate weight layout, trailer scale, activation quantization, and history layout before changing runtime math"
    } else if reasons
        .iter()
        .any(|reason| reason == "rust_ffn_projection_replay_does_not_match_rust_runtime")
    {
        "inspect Rust runtime FFN QK256 dispatch flattening/output reshape before changing reference parity logic"
    } else if reasons.iter().any(|reason| {
        reason == "tiny_ffn_norm_history_delta_amplified_by_qk256_activation_quantization"
            || reason == "ffn_norm_history_delta_explains_ffn_projection_bucket_drift"
    }) {
        "localize the upstream FFN norm/input history delta that feeds FFN up/gate projections"
    } else {
        "continue with FFN activation/product attribution; do not promote claims from this diagnostic"
    }
}

fn build_attn_norm_current_replay(args: &AttnNormCurrentReplayArgs) -> Result<Value> {
    let reference_path = normalize_path(&args.reference)?;
    let cpu_trace_dir = normalize_path(&args.cpu_trace_dir)?;
    let reference_root = read_json(&reference_path)?;
    let reference_records = read_reference_records(&reference_root)?;
    let trace = reference_trace_receipt(&reference_root)?;
    let model_path = args
        .model
        .clone()
        .or_else(|| {
            reference_root.pointer("/model/model_path").and_then(Value::as_str).map(PathBuf::from)
        })
        .unwrap_or_else(|| PathBuf::from(DEFAULT_BITNET_MODEL));
    let model_path = normalize_path(&model_path)?;

    let rust_records = read_rust_trace_dir(&cpu_trace_dir).ok();
    let reference_input = reference_records
        .iter()
        .find(|record| record.stage == "inp_embd")
        .filter(|record| record.values_available && !record.first_values.is_empty());
    let reference_target = reference_records
        .iter()
        .find(|record| record.stage == "attn_norm" && record.layer == Some(0))
        .filter(|record| record.values_available && !record.first_values.is_empty());
    let rust_input = rust_records
        .as_ref()
        .and_then(|records| records.get("embeddings"))
        .filter(|record| !record.first_values.is_empty());
    let rust_target = rust_records
        .as_ref()
        .and_then(|records| records.get("attn_norm"))
        .filter(|record| !record.first_values.is_empty());

    let mut blocked_reasons = Vec::<String>::new();
    if !reference_path.is_file() {
        blocked_reasons.push("reference_layer_trace_receipt_missing".to_string());
    }
    if !model_path.is_file() {
        blocked_reasons.push("model_gguf_missing".to_string());
    }
    if reference_input.is_none() {
        blocked_reasons.push("reference_inp_embd_missing".to_string());
    }
    if reference_target.is_none() {
        blocked_reasons.push("reference_attn_norm_layer0_missing".to_string());
    }
    if rust_records.is_none() {
        blocked_reasons.push("rust_cpu_trace_dir_unavailable".to_string());
    }
    if rust_input.is_none() {
        blocked_reasons.push("rust_embeddings_missing".to_string());
    }
    if rust_target.is_none() {
        blocked_reasons.push("rust_attn_norm_missing".to_string());
    }

    let mut model = json!({
        "path": path_to_string(&model_path),
        "exists": model_path.is_file(),
    });
    let mut weight = json!({
        "name": args.weight,
    });
    let mut replay = Value::Null;

    if model_path.is_file() && reference_input.is_some() && reference_target.is_some() {
        match build_attn_norm_current_replay_body(
            &model_path,
            &args.weight,
            reference_input.expect("checked above"),
            reference_target.expect("checked above"),
            rust_input,
            rust_target,
        ) {
            Ok((model_report, weight_report, replay_report)) => {
                model = model_report;
                weight = weight_report;
                replay = replay_report;
            }
            Err(err) => {
                blocked_reasons.push(format!("attn_norm_current_replay_unavailable:{err}"));
            }
        }
    }

    let scope_mismatch =
        replay.pointer("/scope/scope_mismatch").and_then(Value::as_bool).unwrap_or(false);
    let reference_input_matches_rust_input = replay
        .pointer("/inputs/reference_vs_rust/max_abs_delta")
        .and_then(Value::as_f64)
        .is_some_and(|delta| delta <= 1.0e-6);
    let reference_target_differs_from_rust_target = replay
        .pointer("/targets/reference_vs_rust/max_abs_delta")
        .and_then(Value::as_f64)
        .is_some_and(|delta| delta > 1.0e-9);
    let reference_target_f16_bucket_mismatch_count = replay
        .pointer("/targets/reference_vs_rust_f16/f16_bucket_mismatch_count")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let best_reference_delta = replay
        .pointer("/reference_input_replay/best_vs_reference_target/max_abs_delta")
        .and_then(Value::as_f64);
    let best_rust_delta = replay
        .pointer("/rust_input_replay/best_vs_rust_target/max_abs_delta")
        .and_then(Value::as_f64);

    let current_blocked_reasons = if blocked_reasons.is_empty() {
        classify_attn_norm_current_replay(
            scope_mismatch,
            reference_input_matches_rust_input,
            best_reference_delta,
            best_rust_delta,
            reference_target_differs_from_rust_target,
            reference_target_f16_bucket_mismatch_count,
        )
    } else {
        blocked_reasons.clone()
    };
    let next_action = attn_norm_current_replay_next_action(&current_blocked_reasons);

    Ok(json!({
        "schema_version": 1,
        "receipt_type": "bitnet_reference_attn_norm_current_replay",
        "diagnostic": "bitnet_reference_attn_norm_current_replay",
        "producer": "cargo xtask bitnet-reference-attn-norm-current-replay",
        "created_at": chrono::Utc::now().to_rfc3339(),
        "diagnostic_only": true,
        "claim_allowed": false,
        "promotion_allowed": false,
        "classification": "diagnostic_only",
        "inputs": {
            "reference": path_to_string(&reference_path),
            "cpu_trace_dir": path_to_string(&cpu_trace_dir),
            "model": path_to_string(&model_path),
            "weight": args.weight,
        },
        "reference_trace": {
            "capture_scope": trace.pointer("/capture_scope").cloned().unwrap_or(Value::Null),
            "warmup_skip_policy": trace.pointer("/warmup_skip_policy").cloned().unwrap_or(Value::Null),
            "n_tokens": trace.pointer("/n_tokens").cloned().unwrap_or(Value::Null),
            "n_outputs": trace.pointer("/n_outputs").cloned().unwrap_or(Value::Null),
            "sampled_output_token_index": trace.pointer("/sampled_output_token_index").cloned().unwrap_or(Value::Null),
            "sampled_output_token_id": trace.pointer("/sampled_output_token_id").cloned().unwrap_or(Value::Null),
            "inp_embd": reference_input.map(reference_record_summary).unwrap_or(Value::Null),
            "attn_norm": reference_target.map(reference_record_summary).unwrap_or(Value::Null),
        },
        "rust_trace": {
            "present": rust_records.is_some(),
            "embeddings": rust_input.map(rust_record_summary).unwrap_or(Value::Null),
            "attn_norm": rust_target.map(rust_record_summary).unwrap_or(Value::Null),
        },
        "model": model,
        "weight": weight,
        "replay": replay,
        "decision": {
            "scope_mismatch": scope_mismatch,
            "reference_input_matches_rust_input": reference_input_matches_rust_input,
            "reference_target_differs_from_rust_target": reference_target_differs_from_rust_target,
            "reference_target_f16_bucket_mismatch_count": reference_target_f16_bucket_mismatch_count,
            "best_reference_delta": best_reference_delta,
            "best_rust_delta": best_rust_delta,
            "current_blocked_reasons": current_blocked_reasons,
            "next_action": next_action,
            "claim_allowed": false,
        },
        "not_claims": CRITICAL_NOT_CLAIMS,
    }))
}

fn build_attn_subnorm_replay(args: &AttnSubnormReplayArgs) -> Result<Value> {
    let reference_path = normalize_path(&args.reference)?;
    let cpu_trace_dir = normalize_path(&args.cpu_trace_dir)?;
    let reference_root = read_json(&reference_path)?;
    let reference_records = read_reference_records(&reference_root)?;
    let trace = reference_trace_receipt(&reference_root)?;
    let model_path = args
        .model
        .clone()
        .or_else(|| {
            reference_root.pointer("/model/model_path").and_then(Value::as_str).map(PathBuf::from)
        })
        .unwrap_or_else(|| PathBuf::from(DEFAULT_BITNET_MODEL));
    let model_path = normalize_path(&model_path)?;
    let weight_layer = layer_index_from_blk_weight(&args.weight);
    let layer = args.layer.or(weight_layer).unwrap_or(0);
    let layer_source = if args.layer.is_some() {
        "--layer"
    } else if weight_layer.is_some() {
        "weight_name"
    } else {
        "default_layer0"
    };
    let layer_weight_mismatch =
        args.layer.is_some() && weight_layer.is_some() && args.layer != weight_layer;

    let rust_record_list = read_rust_trace_records(&cpu_trace_dir).ok();
    let reference_input =
        find_reference_trace_record(&reference_records, "attn_value_mix", Some(layer))
            .or_else(|| find_reference_trace_record(&reference_records, "kqv_merged", Some(layer)))
            .filter(|record| record.values_available && !record.first_values.is_empty());
    let reference_target =
        find_reference_trace_record(&reference_records, "attn_sub_norm", Some(layer))
            .filter(|record| record.values_available && !record.first_values.is_empty());
    let rust_input = rust_record_list
        .as_ref()
        .and_then(|records| {
            find_rust_trace_record(records, "attention_value_mix_merged", Some(layer))
        })
        .filter(|record| !record.first_values.is_empty());
    let rust_target = rust_record_list
        .as_ref()
        .and_then(|records| find_rust_trace_record(records, "post_attention_subnorm", Some(layer)))
        .filter(|record| !record.first_values.is_empty());

    let mut blocked_reasons = Vec::<String>::new();
    if !reference_path.is_file() {
        blocked_reasons.push("reference_layer_trace_receipt_missing".to_string());
    }
    if !model_path.is_file() {
        blocked_reasons.push("model_gguf_missing".to_string());
    }
    if layer_weight_mismatch {
        blocked_reasons.push(format!(
            "attention_subnorm_replay_layer_mismatch:requested_layer{}_weight_layer{}",
            layer,
            weight_layer.expect("checked above")
        ));
    }
    if rust_record_list.is_none() {
        blocked_reasons.push("rust_cpu_trace_dir_unavailable".to_string());
    }
    if reference_input.is_none() {
        blocked_reasons.push(format!("reference_attention_value_mix_layer{layer}_missing"));
    }
    if reference_target.is_none() {
        blocked_reasons.push(format!("reference_attn_sub_norm_layer{layer}_missing"));
    }
    if rust_input.is_none() {
        blocked_reasons.push(format!("rust_attention_value_mix_merged_layer{layer}_missing"));
    }
    if rust_target.is_none() {
        blocked_reasons.push(format!("rust_post_attention_subnorm_layer{layer}_missing"));
    }

    let mut model = json!({
        "path": path_to_string(&model_path),
        "exists": model_path.is_file(),
    });
    let mut weight = json!({
        "name": args.weight,
    });
    let mut replay = Value::Null;

    if model_path.is_file()
        && reference_input.is_some()
        && reference_target.is_some()
        && !layer_weight_mismatch
    {
        match build_attn_subnorm_replay_body(
            &model_path,
            &args.weight,
            layer,
            reference_input.expect("checked above"),
            reference_target.expect("checked above"),
            rust_input,
            rust_target,
        ) {
            Ok((model_report, weight_report, replay_report)) => {
                model = model_report;
                weight = weight_report;
                replay = replay_report;
            }
            Err(err) => {
                blocked_reasons.push(format!("attention_subnorm_replay_unavailable:{err}"));
            }
        }
    }

    let scope_mismatch =
        replay.pointer("/scope/scope_mismatch").and_then(Value::as_bool).unwrap_or(false);
    let reference_input_matches_rust_input = replay
        .pointer("/inputs/reference_vs_rust/max_abs_delta")
        .and_then(Value::as_f64)
        .is_some_and(|delta| delta <= 1.0e-6);
    let reference_target_differs_from_rust_target = replay
        .pointer("/targets/reference_vs_rust/max_abs_delta")
        .and_then(Value::as_f64)
        .is_some_and(|delta| delta > 1.0e-9);
    let reference_target_f16_bucket_mismatch_count = replay
        .pointer("/targets/reference_vs_rust_f16/f16_bucket_mismatch_count")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let best_reference_delta = replay
        .pointer("/reference_input_replay/best_vs_reference_target/max_abs_delta")
        .and_then(Value::as_f64);
    let best_rust_delta = replay
        .pointer("/rust_input_replay/best_vs_rust_target/max_abs_delta")
        .and_then(Value::as_f64);

    let current_blocked_reasons = if blocked_reasons.is_empty() {
        classify_attn_subnorm_replay(
            scope_mismatch,
            reference_input_matches_rust_input,
            best_reference_delta,
            best_rust_delta,
            reference_target_differs_from_rust_target,
            reference_target_f16_bucket_mismatch_count,
        )
    } else {
        blocked_reasons.clone()
    };
    let next_action = attn_subnorm_replay_next_action(&current_blocked_reasons);

    Ok(json!({
        "schema_version": 1,
        "receipt_type": "bitnet_reference_attn_subnorm_replay",
        "diagnostic": "bitnet_reference_attn_subnorm_replay",
        "producer": "cargo xtask bitnet-reference-attn-subnorm-replay",
        "created_at": chrono::Utc::now().to_rfc3339(),
        "diagnostic_only": true,
        "claim_allowed": false,
        "promotion_allowed": false,
        "classification": "diagnostic_only",
        "inputs": {
            "reference": path_to_string(&reference_path),
            "cpu_trace_dir": path_to_string(&cpu_trace_dir),
            "model": path_to_string(&model_path),
            "weight": args.weight,
            "requested_layer": args.layer,
            "inferred_weight_layer": weight_layer,
            "selected_layer": layer,
            "layer_source": layer_source,
        },
        "reference_trace": {
            "capture_scope": trace.pointer("/capture_scope").cloned().unwrap_or(Value::Null),
            "warmup_skip_policy": trace.pointer("/warmup_skip_policy").cloned().unwrap_or(Value::Null),
            "n_tokens": trace.pointer("/n_tokens").cloned().unwrap_or(Value::Null),
            "n_outputs": trace.pointer("/n_outputs").cloned().unwrap_or(Value::Null),
            "sampled_output_token_index": trace.pointer("/sampled_output_token_index").cloned().unwrap_or(Value::Null),
            "sampled_output_token_id": trace.pointer("/sampled_output_token_id").cloned().unwrap_or(Value::Null),
            "attention_value_mix": reference_input.map(reference_record_summary).unwrap_or(Value::Null),
            "attn_sub_norm": reference_target.map(reference_record_summary).unwrap_or(Value::Null),
        },
        "rust_trace": {
            "present": rust_record_list.is_some(),
            "attention_value_mix_merged": rust_input.map(rust_record_summary).unwrap_or(Value::Null),
            "post_attention_subnorm": rust_target.map(rust_record_summary).unwrap_or(Value::Null),
        },
        "model": model,
        "weight": weight,
        "replay": replay,
        "decision": {
            "scope_mismatch": scope_mismatch,
            "reference_input_matches_rust_input": reference_input_matches_rust_input,
            "reference_target_differs_from_rust_target": reference_target_differs_from_rust_target,
            "reference_target_f16_bucket_mismatch_count": reference_target_f16_bucket_mismatch_count,
            "best_reference_delta": best_reference_delta,
            "best_rust_delta": best_rust_delta,
            "selected_layer": layer,
            "current_blocked_reasons": current_blocked_reasons,
            "next_action": next_action,
            "claim_allowed": false,
        },
        "not_claims": CRITICAL_NOT_CLAIMS,
    }))
}

